<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Değerlendirme yaz</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:650px;margin:40px auto;padding:0 18px}.panel{background:white;padding:25px;border-radius:14px}label{display:block;font-weight:700;margin:16px 0 7px}select,textarea{width:100%;box-sizing:border-box;padding:12px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}textarea{min-height:150px}button{background:#176b50;color:white;border:0;border-radius:8px;padding:13px 18px;font-weight:700}</style></head><body><main class="wrap"><h1>Konaklamayı değerlendirin</h1><p><?= e($booking['title']) ?></p><form method="post" action="/account/reviews"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><section class="panel"><label>Puanınız</label><select name="rating" required><option value="5">5 - Mükemmel</option><option value="4">4 - Çok iyi</option><option value="3">3 - İyi</option><option value="2">2 - Geliştirilebilir</option><option value="1">1 - Kötü</option></select><label>Yorumunuz</label><textarea name="body" maxlength="3000" placeholder="Konaklama deneyiminizi paylaşın..."></textarea><p><button type="submit">Değerlendirmeyi gönder</button></p></section></form></main></body></html>